<?php require "auth.php"; $msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["nama"]??"");if($n!==""){$s=$conn->prepare("INSERT IGNORE INTO kategori(nama_kategori) VALUES(?)");$s->bind_param("s",$n);$s->execute();$msg="Kategori ditambahkan atau sudah tersedia.";}}$rows=$conn->query("SELECT * FROM kategori ORDER BY id DESC");?><!doctype html><html lang="id"><head><meta charset="utf-8"><link rel="stylesheet" href="style.css"><title>Kategori</title></head><body><header><b>Kantin POS</b><nav><a href="dashboard.php">Dashboard</a><a href="barang.php">Barang</a><a href="kategori.php">Kategori</a><a href="transaksi.php">Transaksi</a><a href="logout.php">Keluar</a></nav></header><main class="wide"><section class="panel"><h1>Kategori</h1><p><?=$msg?></p><form method="post"><label>Nama kategori</label><input name="nama" required><button>Tambah Kategori</button></form></section><section class="panel"><table><tr><th>ID</th><th>Nama kategori</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r["id"]?></td><td><?=htmlspecialchars($r["nama_kategori"])?></td></tr><?php endwhile;?></table></section></main></body></html>